before:
Complete local Rust example; the app itself does not execute it:
```rust
use std::thread;

fn main() {
    let text = String::from("read");
    let worker = thread::spawn(move || text.len());
    let length = worker.join().expect("worker panicked");
    println!("{length}");
}
```

